"""Self-contained apply script - run from inside your HealthCross project
folder (the one with .venv in it): python3 apply_daman_tob_and_dha_claims_format3.py
Writes/overwrites the files below, then git add/commit/push yourself.
"""
import base64, os

FILES = {
    'app/api/routes_cases.py': '',
    'app/ingestion/claims_report.py': '',
    'app/ingestion/daman_tob.py': '',
    'app/reference/benefit_category_mapping.py': '',
    'tests/test_ingestion_claims_report_format3.py': '',
    'tests/test_ingestion_daman_tob.py': '',
}


SCRIPT_DIR = os.path.dirname(os.path.abspath(__file__))

def main():
    for relpath, b64 in FILES.items():
        target = os.path.join(SCRIPT_DIR, relpath)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        data = base64.b64decode(b64)
        with open(target, "wb") as f:
            f.write(data)
        print(f"Wrote {relpath} ({len(data)} bytes)")
    print()
    print("Done. Now run:")
    print("  git add -A")
    print('  git commit -m "Add Daman TOB parser for New Business quoting; fix DHA claims report parsing"')
    print("  git push -u origin claude/underwriting-intelligence-tools-v0xh0j")

if __name__ == "__main__":
    main()
